function segitigaBintang(n) {
  const baris = [];
  for (let i = 1; i <= n; i++) baris.push(" ".repeat(n - i) + "*".repeat(i));
  return baris;
}

solutions.go:
import "strings"

func segitigaBintang(n int) []string {
	baris := []string{}
	for i := 1; i <= n; i++ {
		baris = append(baris, strings.Repeat(" ", n-i)+strings.Repeat("*", i))
	}
	return baris
}
